ALTER TABLE "documents" ADD CONSTRAINT "documents_versions_after_processing" CHECK ("documents"."status" IN ('uploaded', 'processing') OR "documents"."versions" IS NOT NULL);--> statement-breakpoint
ALTER TABLE "documents" ADD CONSTRAINT "documents_failed_has_error" CHECK ("documents"."status" <> 'failed' OR "documents"."error" IS NOT NULL);--> statement-breakpoint
ALTER TABLE "documents" ADD CONSTRAINT "documents_auto_approved_routing" CHECK ("documents"."status" <> 'auto_approved' OR COALESCE("documents"."routing" ->> 'decision' = 'auto_approve' AND jsonb_array_length("documents"."routing" -> 'reasons') = 0, false));--> statement-breakpoint
ALTER TABLE "documents" ADD CONSTRAINT "documents_auto_approved_no_block_fail" CHECK ("documents"."status" <> 'auto_approved' OR (jsonb_array_length("documents"."rule_results") > 0 AND NOT jsonb_path_exists("documents"."rule_results", '$[*] ? (@.severity == "block" && @.passed == false)')));--> statement-breakpoint
ALTER TABLE "documents" ADD CONSTRAINT "documents_extracted_has_result" CHECK ("documents"."status" NOT IN ('extracted', 'auto_approved') OR ("documents"."classification" IS NOT NULL AND "documents"."extraction" IS NOT NULL));--> statement-breakpoint
ALTER TABLE "documents" ADD CONSTRAINT "documents_uploaded_is_clean" CHECK ("documents"."status" <> 'uploaded' OR ("documents"."classification" IS NULL AND "documents"."extraction" IS NULL AND "documents"."routing" IS NULL AND "documents"."versions" IS NULL AND "documents"."error" IS NULL AND "documents"."rule_results" = '[]'::jsonb));